[{"order":1,"type":"heading","text":"Decorators in Node.js: Adding Metadata to Classes and Methods"},{"order":2,"type":"paragraph","text":"Decorators are a powerful feature in JavaScript (and TypeScript) that allow you to modify or extend the behavior of classes, methods, properties, or parameters. They provide a clean and declarative way to add metadata or functionality to your code. While native JavaScript support for decorators is still evolving, they are widely used in TypeScript and can be used in Node.js with the help of transpilers like Babel."},{"order":3,"type":"subheading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Node.js installed (version 12 or higher recommended)"},{"order":5,"type":"bullet_point","text":"npm or yarn package manager"},{"order":6,"type":"bullet_point","text":"Babel configured for decorator support (using @babel/core, @babel/cli, @babel/plugin-proposal-decorators, and @babel/plugin-proposal-class-properties)"},{"order":7,"type":"subheading","text":"Setting up Babel for Decorator Support"},{"order":8,"type":"paragraph","text":"First, initialize a new Node.js project:"},{"order":9,"type":"code","text":"mkdir decorators-example
cd decorators-example
npm init -y"},{"order":10,"type":"paragraph","text":"Next, install the necessary Babel packages:"},{"order":11,"type":"code","text":"npm install --save-dev @babel/core @babel/cli @babel/plugin-proposal-decorators @babel/plugin-proposal-class-properties"},{"order":12,"type":"paragraph","text":"Create a `.babelrc` file in the root of your project with the following configuration:"},{"order":13,"type":"code","text":"{
  "plugins": [
    ["@babel/plugin-proposal-decorators", { "legacy": true }],
    ["@babel/plugin-proposal-class-properties", { "loose": true }]
  ]
}"},{"order":14,"type":"subheading","text":"Creating a Simple Decorator"},{"order":15,"type":"paragraph","text":"Let's create a simple decorator that logs a message when a method is called. Create a file named `index.js`:"},{"order":16,"type":"code","text":"function logMethod(target, propertyKey, descriptor) {
  const originalMethod = descriptor.value;

  descriptor.value = function (...args) {
    console.log(`Calling method: ${propertyKey}`);
    const result = originalMethod.apply(this, args);
    console.log(`Method ${propertyKey} returned:`, result);
    return result;
  };

  return descriptor;
}

class MyClass {
  @logMethod
  add(a, b) {
    return a + b;
  }
}

const myInstance = new MyClass();
const sum = myInstance.add(5, 3);
console.log('Sum:', sum);"},{"order":17,"type":"paragraph","text":"In this example, `logMethod` is a decorator that takes three arguments: `target` (the class prototype), `propertyKey` (the name of the method), and `descriptor` (the property descriptor). It wraps the original method with a new function that logs a message before and after the method is called."},{"order":18,"type":"subheading","text":"Running the Code"},{"order":19,"type":"paragraph","text":"Add a script to your `package.json` to run the code using Babel:"},{"order":20,"type":"code","text":""scripts": {
  "start": "babel-node index.js"
}"},{"order":21,"type":"paragraph","text":"Now, run the code:"},{"order":22,"type":"code","text":"npm start"},{"order":23,"type":"paragraph","text":"You should see the log messages from the decorator in the console."},{"order":24,"type":"subheading","text":"Adding Metadata with Decorators"},{"order":25,"type":"paragraph","text":"Decorators can also be used to add metadata to classes and methods. This metadata can then be used by other parts of your application. Here's an example:"},{"order":26,"type":"code","text":"const classMetadataKey = Symbol('classMetadata');
const methodMetadataKey = Symbol('methodMetadata');

function setClassMetadata(metadata) {
  return function (target) {
    Reflect.defineMetadata(classMetadataKey, metadata, target);
  };
}

function setMethodMetadata(metadata) {
  return function (target, propertyKey, descriptor) {
    Reflect.defineMetadata(methodMetadataKey, metadata, descriptor.value);
  };
}

function getClassMetadata(target) {
  return Reflect.getMetadata(classMetadataKey, target);
}

function getMethodMetadata(target, propertyKey) {
  // Get the method from the prototype
  const method = target.prototype[propertyKey];
  return Reflect.getMetadata(methodMetadataKey, method);
}


@setClassMetadata({ description: 'This is a class with metadata' })
class MyClass {
  @setMethodMetadata({ description: 'This is a method with metadata' })
  myMethod() {
    return 'Hello, world!';
  }
}

// Ensure you have reflect-metadata installed: npm install reflect-metadata --save
require('reflect-metadata');

const myInstance = new MyClass();

const classMetadata = getClassMetadata(MyClass);
const methodMetadata = getMethodMetadata(myInstance, 'myMethod');

console.log('Class Metadata:', classMetadata);
console.log('Method Metadata:', methodMetadata);"},{"order":27,"type":"paragraph","text":"In this example, we use the `reflect-metadata` library to store and retrieve metadata.  Make sure to install it using `npm install reflect-metadata --save`. The `setClassMetadata` and `setMethodMetadata` decorators add metadata to the class and method, respectively. The `getClassMetadata` and `getMethodMetadata` functions retrieve the metadata."},{"order":28,"type":"subheading","text":"Important Considerations"},{"order":29,"type":"bullet_point","text":"Decorators are still a proposal in JavaScript, so their syntax and behavior may change in the future."},{"order":30,"type":"bullet_point","text":"Using decorators requires a transpiler like Babel or TypeScript."},{"order":31,"type":"bullet_point","text":"The `reflect-metadata` library is often used in conjunction with decorators to store and retrieve metadata."},{"order":32,"type":"subheading","text":"Conclusion"},{"order":33,"type":"paragraph","text":"Decorators provide a powerful and elegant way to add functionality and metadata to your classes and methods in Node.js. By using Babel or TypeScript, you can take advantage of this feature to write cleaner and more maintainable code."}]
